-- 2) 逐个旧资源迁移。
-- admin/adminupload upload → system:admin-upload:upload
UPDATE `fun_admin_menu` t JOIN (SELECT MIN(`id`) AS `id` FROM `fun_permission` WHERE `obj` = 'admin/adminupload' AND `act` = 'upload' AND `resource_type` = 'route' AND `deleted_at` IS NULL) f ON t.`permission_id` = f.`id` JOIN `fun_permission` e ON e.`code` = 'system:admin-upload:upload' AND e.`id` <> f.`id` SET t.`permission_id` = e.`id`;
UPDATE `fun_permission_field` t JOIN (SELECT MIN(`id`) AS `id` FROM `fun_permission` WHERE `obj` = 'admin/adminupload' AND `act` = 'upload' AND `resource_type` = 'route' AND `deleted_at` IS NULL) f ON t.`permission_id` = f.`id` JOIN `fun_permission` e ON e.`code` = 'system:admin-upload:upload' AND e.`id` <> f.`id` SET t.`permission_id` = e.`id`;
UPDATE `fun_permission` t JOIN (SELECT MIN(`id`) AS `id` FROM `fun_permission` WHERE `obj` = 'admin/adminupload' AND `act` = 'upload' AND `resource_type` = 'route' AND `deleted_at` IS NULL) f ON t.`pid` = f.`id` JOIN `fun_permission` e ON e.`code` = 'system:admin-upload:upload' AND e.`id` <> f.`id` SET t.`pid` = e.`id`;
UPDATE `fun_admin_menu` m JOIN (SELECT MIN(`id`) AS `id` FROM `fun_permission` WHERE `obj` = 'admin/adminupload' AND `act` = 'upload' AND `resource_type` = 'route' AND `deleted_at` IS NULL) f JOIN `fun_permission` o ON o.`id` = f.`id` JOIN `fun_permission` k ON k.`id` = IF(EXISTS (SELECT 1 FROM `fun_permission` e WHERE e.`code` = 'system:admin-upload:upload' AND e.`id` <> o.`id`), (SELECT e.`id` FROM `fun_permission` e WHERE e.`code` = 'system:admin-upload:upload' LIMIT 1), o.`id`)
  SET m.`query` = REGEXP_REPLACE(REGEXP_REPLACE(m.`query`, CONCAT('(^|&)permission=', REPLACE(REPLACE(o.`code`, '.', '\\.'), ':', '%3A'), '(&|$)'), CONCAT('$1permission=', 'system%3Aadmin-upload%3Aupload', '$2')),
    CONCAT('(^|&)permission=', REPLACE(o.`code`, '.', '\\.'), '(&|$)'), CONCAT('$1permission=', 'system:admin-upload:upload', '$2'))
  WHERE m.`permission_id` = k.`id` AND o.`code` IS NOT NULL AND o.`code` <> 'system:admin-upload:upload';
INSERT IGNORE INTO `fun_casbin_rule` (`ptype`,`v0`,`v1`,`v2`,`v3`,`v4`,`v5`,`rule_hash`)
  SELECT 'p', r.`v0`, r.`v1`, 'system/admin-upload', 'upload', '', '', SHA2(CONCAT_WS(CHAR(31), 'p', r.`v0`, r.`v1`, 'system/admin-upload', 'upload'), 256)
  FROM `fun_casbin_rule` r JOIN (SELECT MIN(`id`) AS `id` FROM `fun_permission` WHERE `obj` = 'admin/adminupload' AND `act` = 'upload' AND `resource_type` = 'route' AND `deleted_at` IS NULL) f ON f.`id` IS NOT NULL WHERE r.`ptype` = 'p' AND r.`v2` = 'admin/adminupload' AND r.`v3` = 'upload';
