UPDATE `fun_permission` e JOIN (SELECT MIN(`id`) AS `id` FROM `fun_permission` WHERE `obj` = 'admin/adminupload' AND `act` = 'upload' AND `resource_type` = 'route' AND `deleted_at` IS NULL) f JOIN `fun_permission` o ON o.`id` = f.`id` SET e.`is_public` = GREATEST(e.`is_public`, o.`is_public`), e.`status` = LEAST(e.`status`, o.`status`) WHERE e.`code` = 'system:admin-upload:upload' AND e.`id` <> o.`id`;
UPDATE `fun_permission` o JOIN (SELECT MIN(`id`) AS `id` FROM `fun_permission` WHERE `obj` = 'admin/adminupload' AND `act` = 'upload' AND `resource_type` = 'route' AND `deleted_at` IS NULL) f ON o.`id` = f.`id` LEFT JOIN `fun_permission` e ON e.`code` = 'system:admin-upload:upload' AND e.`id` <> o.`id`
  SET o.`status` = IF(e.`id` IS NULL, o.`status`, 0), o.`code` = IF(e.`id` IS NULL, 'system:admin-upload:upload', o.`code`), o.`obj` = IF(e.`id` IS NULL, 'system/admin-upload', o.`obj`), o.`act` = IF(e.`id` IS NULL, 'upload', o.`act`);

