UPDATE `fun_admin_menu` m JOIN `fun_permission` p ON p.`code` = 'system:dict:types' AND p.`status` = 1
  SET m.`permission_id` = p.`id`, m.`query` = IF(m.`query` REGEXP '(^|&)permission=', REGEXP_REPLACE(m.`query`, '(^|&)permission=[^&]*', CONCAT('$1permission=', 'system:dict:types')), CONCAT(m.`query`, IF(m.`query` = '', '', '&'), 'permission=', 'system:dict:types'))
  WHERE m.`source_type` = 'admin_web' AND m.`query` REGEXP '(^|&)name=SystemDict(&|$)';
